document.addEventListener('DOMContentLoaded',()=>{fetch('cv.json?v=20260527').then(response=>{if(!response.ok)throw new Error("No se pudo cargar el JSON");return response.json();}).then(data=>{renderPortfolio(data);initInteractions();}).catch(err=>{console.error('Error:',err);document.getElementById('app').innerHTML=`<p style="text-align:center; padding:50px;">Error cargando datos. Revisa la consola (F12).</p>`;});});function renderPortfolio(data){const app=document.getElementById('app');app.innerHTML=`
                <!-- NAVBAR -->
                <nav class="glass-nav">
                    <div class="nav-container">
                        <a href="#profile" class="nav-logo">MA.</a>
                        <ul class="nav-links">
                            <li><a href="#profile">Inicio</a></li>
                            <li><a href="/experiencia.html">Experiencia</a></li>
                            <li><a href="/servicios.html">Servicios</a></li>
                            <li><a href="/proyectos.html">Proyectos</a></li>
                            <li><a href="#education">Formación</a></li>
                            <li><a href="#skills">Skills</a></li>
                        </ul>
                        <a href="mailto:${data.personal.email}" class="btn-contact">Contactar</a>
                    </div>
                </nav>

                <!-- HERO / PERFIL -->
                <header id="profile" class="hero-section scroll-trigger">
                    <div class="hero-container">
                        <div class="hero-text">
                            <span class="greeting">Hola, soy</span>
                            <h1>${data.personal.name}</h1>
                            <h2 class="subtitle">${data.personal.role}</h2>
                            <p class="summary">${data.profile}</p>
                            
                            <div class="hero-actions">
                                <a href="${data.personal.linkedinUrl}" target="_blank" rel="noopener noreferrer" class="btn-social">
                                    <i class="fa-brands fa-linkedin"></i> LinkedIn
                                </a>
                                <span class="location-badge">
                                    <i class="fa-solid fa-location-dot"></i> ${data.personal.location}
                                </span>
                            </div>
                        </div>
                        <div class="hero-visual">
                            <div class="image-wrapper">
                                <!-- Si usas foto local cambia la url en el json -->
                                <img src="${data.personal.photoUrl}" alt="${data.personal.name}">
                            </div>
                        </div>
                    </div>
                </header>

                <main class="main-content">
                    
                    <!-- EXPERIENCIA -->
                    <section id="experience" class="section-block scroll-trigger">
                        <div class="section-header">
                            <h2 class="section-title">Experiencia</h2>
                            <div class="separator"></div>
                        </div>
                        <div class="timeline-container">
                            ${data.experience.map(exp => `<div class="timeline-card"><div class="card-date">${exp.dates}</div><div class="card-content"><h3>${exp.position}</h3><h4 class="company-name"><i class="fa-solid fa-building"></i> ${exp.company}</h4><ul>${exp.description.map(d=>`<li>${d}</li>`).join('')}</ul></div></div>`).join('')}
                        </div>
                    </section>

                    <!-- EDUCACIÓN -->
                    <section id="education" class="section-block scroll-trigger">
                        <div class="section-header">
                            <h2 class="section-title">Formación</h2>
                            <div class="separator"></div>
                        </div>
                        <div class="grid-2-col">
                            ${data.education.map(edu => `<div class="education-card"><div class="edu-icon"><i class="fa-solid fa-graduation-cap"></i></div><div class="edu-info"><h3>${edu.degree}</h3><span class="institution">${edu.institution}</span><span class="year">${edu.dates}</span><p class="details">${edu.details}</p></div></div>`).join('')}
                        </div>
                    </section>

                    <!-- SKILLS -->
                    <section id="skills" class="section-block scroll-trigger">
                        <div class="section-header">
                            <h2 class="section-title">Habilidades</h2>
                            <div class="separator"></div>
                        </div>
                        
                        <div class="skills-wrapper">
                            <div class="skills-col">
                                <h3 class="col-title">Tecnologías</h3>
                                <div class="tech-list">
                                    ${data.hardSkills.map(s => `<div class="tech-item"><div class="tech-header"><span><i class="${s.icon}"></i> ${s.name}</span><span class="pct">${s.percent}%</span></div><div class="skill-track"><div class="skill-progress" style="width: ${s.percent}%"></div></div></div>`).join('')}
                                </div>
                            </div>

                            <div class="skills-col">
                                <h3 class="col-title">Idiomas & Aptitudes</h3>
                                <div class="lang-grid">
                                    ${data.languages.map(l => `<div class="lang-box"><span class="lang-name">${l.name}</span><span class="lang-level">${l.level}</span></div>`).join('')}
                                </div>
                                <div class="soft-tags">
                                    ${data.softSkills.map(s => `<span class="pill">${s.name}</span>`).join('')}
                                </div>
                            </div>
                        </div>
                    </section>
                </main>

                <footer class="main-footer">
                    <p>© ${new Date().getFullYear()} ${data.personal.name} | Full Stack Developer</p>
                </footer>
            `;}
function initInteractions(){const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');}else{entry.target.classList.remove('is-visible');}});},{threshold:0.15,rootMargin:"0px 0px -50px 0px"});document.querySelectorAll('.scroll-trigger').forEach(el=>observer.observe(el));const sections=document.querySelectorAll('header, section');const navLi=document.querySelectorAll('.nav-links li a');window.addEventListener('scroll',()=>{let current='';sections.forEach(section=>{const sectionTop=section.offsetTop;if(window.scrollY>=(sectionTop-150)){current=section.getAttribute('id');}});navLi.forEach(a=>{a.classList.remove('active-link');if(a.getAttribute('href')==='#'+current){a.classList.add('active-link');}});});}
